const ASPECT = "1920 / 1080"

// Shader Lab runs one private looping <video> per layer and never aligns them.
// This records those elements and re-seeks the second one whenever it drifts
// more than 0.05s (~1.5 frames @30fps) from the first (the master clock).
function startVideoSync(sources: string[]) {
  const created = new Set<HTMLVideoElement>()
  const orig = document.createElement.bind(document)
  document.createElement = ((tag: string, o?: ElementCreationOptions) => {
    const el = orig(tag, o)
    if (typeof tag === "string" && tag.toLowerCase() === "video") created.add(el as HTMLVideoElement)
    return el
  }) as typeof document.createElement
  const find = (src: string) => {
    const abs = new URL(src, location.href).href
    for (const v of created) {
      if (!v.getAttribute("src")) { created.delete(v); continue }
      if (v.src === abs) return v
    }
    return null
  }
  let raf = 0
  const tick = () => {
    const [m, ...slaves] = sources.map(find).filter((v): v is HTMLVideoElement => !!v)
    if (m && m.readyState >= 2 && !m.paused) {
      for (const s of slaves) {
        if (s.readyState < 1 || s.seeking || !s.duration) continue
        const dur = Math.min(m.duration, s.duration)
        let d = m.currentTime - s.currentTime
        if (Number.isFinite(dur)) { if (d > dur / 2) d -= dur; else if (d < -dur / 2) d += dur }
        if (Math.abs(d) > 0.05) s.currentTime = m.currentTime % s.duration
      }
    }
    raf = requestAnimationFrame(tick)
  }
  raf = requestAnimationFrame(tick)
  return () => { cancelAnimationFrame(raf); document.createElement = orig }
}

function Fallback() {
  const fill = { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" } as const
  return (
    <>
      <video src="/videos/chrome_ydCa5YsssPi9i_1.webm" autoPlay muted loop playsInline style={fill} />
      <video src="/videos/chrome_ydCa5YPi9i.webm" autoPlay muted loop playsInline style={{ ...fill, mixBlendMode: "screen" }} />
    </>
  )
}

export function AsciiVideo({ className }: { className?: string }) {
  const [failed, setFailed] = useState(false)
  useEffect(() => (failed ? undefined : startVideoSync(["/videos/chrome_ydCa5YsssPi9i_1.webm", "/videos/chrome_ydCa5YPi9i.webm"])), [failed])
  return (
    <div
      className={className}
      style={{ position: "relative", width: "100%", aspectRatio: ASPECT, overflow: "hidden" }}
    >
      {failed ? (
        <Fallback />
      ) : (
        <ShaderLabComposition
          config={config}
          onRuntimeError={(m) => m && setFailed(true)}
        />
      )}
    </div>
  )
}
